#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

static char *dup_str(const char *src) { size_t n = strlen(src); char *dst = (char *)malloc(n + 1); if (!dst) exit(1); memcpy(dst, src, n + 1); return dst; }

typedef struct {
    char *s;
    int n;
    char ***rows;
    int *cols;
    int size;
    int cap;
    char **path;
    int depth;
} Ctx;

static void add_result(Ctx *ctx) {
    if (ctx->size == ctx->cap) {
        ctx->cap *= 2;
        ctx->rows = (char ***)realloc(ctx->rows, ctx->cap * sizeof(char **));
        ctx->cols = (int *)realloc(ctx->cols, ctx->cap * sizeof(int));
    }
    char **row = (char **)malloc(ctx->depth * sizeof(char *));
    for (int i = 0; i < ctx->depth; ++i) {
        row[i] = dup_str(ctx->path[i]);
    }
    ctx->rows[ctx->size] = row;
    ctx->cols[ctx->size] = ctx->depth;
    ++ctx->size;
}

static bool is_palindrome(const char *s, int l, int r) {
    while (l < r) {
        if (s[l++] != s[r--]) return false;
    }
    return true;
}

static void dfs(Ctx *ctx, int start) {
    if (start == ctx->n) {
        add_result(ctx);
        return;
    }
    for (int end = start; end < ctx->n; ++end) {
        if (!is_palindrome(ctx->s, start, end)) continue;
        int len = end - start + 1;
        char *piece = (char *)malloc((size_t)len + 1);
        memcpy(piece, ctx->s + start, (size_t)len);
        piece[len] = '\0';
        ctx->path[ctx->depth++] = piece;
        dfs(ctx, end + 1);
        --ctx->depth;
        free(piece);
    }
}

char ***partition(char *s, int *returnSize, int **returnColumnSizes) {
    Ctx ctx;
    ctx.s = s;
    ctx.n = (int)strlen(s);
    ctx.cap = 64;
    ctx.size = 0;
    ctx.rows = (char ***)malloc(ctx.cap * sizeof(char **));
    ctx.cols = (int *)malloc(ctx.cap * sizeof(int));
    ctx.path = (char **)malloc(ctx.n * sizeof(char *));
    ctx.depth = 0;

    dfs(&ctx, 0);

    free(ctx.path);
    *returnSize = ctx.size;
    *returnColumnSizes = ctx.cols;
    return ctx.rows;
}

static char *parse_string(const char *line) {
    const char *q1 = strchr(line, '"');
    if (!q1) return NULL;
    const char *q2 = strrchr(q1 + 1, '"');
    if (!q2 || q2 <= q1) return NULL;
    size_t len = (size_t)(q2 - q1 - 1);
    char *s = (char *)malloc(len + 1);
    memcpy(s, q1 + 1, len);
    s[len] = '\0';
    return s;
}

int main(void) {
    char line[1024];
    if (!fgets(line, sizeof(line), stdin)) return 0;
    char *s = parse_string(line);

    int returnSize = 0;
    int *returnColumnSizes = NULL;
    char ***result = partition(s, &returnSize, &returnColumnSizes);

    printf("[");
    for (int i = 0; i < returnSize; ++i) {
        printf("[");
        for (int j = 0; j < returnColumnSizes[i]; ++j) {
            printf("\"%s\"", result[i][j]);
            if (j + 1 < returnColumnSizes[i]) printf(",");
            free(result[i][j]);
        }
        printf("]");
        free(result[i]);
        if (i + 1 < returnSize) printf(",");
    }
    printf("]\n");

    free(result);
    free(returnColumnSizes);
    free(s);
    return 0;
}

