using namespace std;

class Solution {
public:
    vector<vector<string>> partition(string s) {
        int n = static_cast<int>(s.size());
        vector<vector<bool>> pal(n, vector<bool>(n, false));

        for (int i = n - 1; i >= 0; --i) {
            for (int j = i; j < n; ++j) {
                pal[i][j] = (s[i] == s[j]) &&
                            (j - i < 2 || pal[i + 1][j - 1]);
            }
        }

        vector<vector<vector<string>>> dp(n);
        for (int i = n - 1; i >= 0; --i) {
            for (int j = i; j < n; ++j) {
                if (!pal[i][j]) continue;

                string part = s.substr(i, j - i + 1);
                if (j == n - 1) {
                    dp[i].push_back({part});
                } else {
                    for (const auto& suffix : dp[j + 1]) {
                        vector<string> candidate;
                        candidate.reserve(suffix.size() + 1);
                        candidate.push_back(part);
                        candidate.insert(candidate.end(), suffix.begin(), suffix.end());
                        dp[i].push_back(std::move(candidate));
                    }
                }
            }
        }
        return dp[0];
    }
};

static string parseString(const string& line) {
    size_t first = line.find('"');
    size_t last = line.rfind('"');
    if (first == string::npos || last <= first) throw runtime_error("Invalid input");
    return line.substr(first + 1, last - first - 1);
}

int main() {
    string line;
    getline(cin, line);
    string s = parseString(line);
    auto result = Solution().partition(s);

    cout << "[";
    for (size_t i = 0; i < result.size(); ++i) {
        if (i > 0) cout << ",";
        cout << "[";
        for (size_t j = 0; j < result[i].size(); ++j) {
            if (j > 0) cout << ",";
            cout << "\"" << result[i][j] << "\"";
        }
        cout << "]";
    }
    cout << "]\n";
    return 0;
}

