import java.io.*;
import java.util.*;

class Solution {
    public List<List<String>> partition(String s) {
        int n = s.length();
        boolean[][] pal = new boolean[n][n];

        for (int i = n - 1; i >= 0; --i) {
            for (int j = i; j < n; ++j) {
                pal[i][j] = s.charAt(i) == s.charAt(j)
                        && (j - i < 2 || pal[i + 1][j - 1]);
            }
        }

        List<List<List<String>>> dp = new ArrayList<>();
        for (int i = 0; i < n; ++i) {
            dp.add(new ArrayList<>());
        }

        for (int i = n - 1; i >= 0; --i) {
            for (int j = i; j < n; ++j) {
                if (!pal[i][j]) {
                    continue;
                }
                String part = s.substring(i, j + 1);
                if (j == n - 1) {
                    List<String> one = new ArrayList<>();
                    one.add(part);
                    dp.get(i).add(one);
                } else {
                    for (List<String> suffix : dp.get(j + 1)) {
                        List<String> candidate = new ArrayList<>(suffix.size() + 1);
                        candidate.add(part);
                        candidate.addAll(suffix);
                        dp.get(i).add(candidate);
                    }
                }
            }
        }
        return dp.get(0);
    }
}

public class Main {
    private static String parseString(String line) {
        int first = line.indexOf('"');
        int last = line.lastIndexOf('"');
        if (first < 0 || last <= first) {
            throw new IllegalArgumentException("Invalid input");
        }
        return line.substring(first + 1, last);
    }

    private static String toJson(List<List<String>> result) {
        StringBuilder out = new StringBuilder("[");
        for (int i = 0; i < result.size(); ++i) {
            if (i > 0) out.append(',');
            out.append('[');
            for (int j = 0; j < result.get(i).size(); ++j) {
                if (j > 0) out.append(',');
                out.append('"').append(result.get(i).get(j)).append('"');
            }
            out.append(']');
        }
        return out.append(']').toString();
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        String s = parseString(line);
        System.out.println(toJson(new Solution().partition(s)));
    }
}

