'use strict';

const readline = require('readline');

function partition(s) {
    const n = s.length;
    const pal = Array.from({ length: n }, () => Array(n).fill(false));

    for (let i = n - 1; i >= 0; --i) {
        for (let j = i; j < n; ++j) {
            pal[i][j] =
                s[i] === s[j] &&
                (j - i < 2 || pal[i + 1][j - 1]);
        }
    }

    const dp = Array.from({ length: n }, () => []);

    for (let i = n - 1; i >= 0; --i) {
        for (let j = i; j < n; ++j) {
            if (!pal[i][j]) continue;

            const part = s.slice(i, j + 1);
            if (j === n - 1) {
                dp[i].push([part]);
            } else {
                for (const suffix of dp[j + 1]) {
                    dp[i].push([part, ...suffix]);
                }
            }
        }
    }

    return dp[0];
}

